// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/kernel.h>
#include <linux/limits.h>
#include <linux/slab.h>
#include <linux/string.h>

static void strncasecmp_zero_len_test(struct kunit *test)
{
	/* len == 0 must return before any byte is examined */
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "xyz", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(NULL, NULL, 0), 0);
}

static void strncasecmp_equal_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abc", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abc", 10), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABC", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ABC", "abc", 4), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("Hello, World!", "hELLO, wORLD!", 13), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABC", SIZE_MAX), 0);
}

static void strncasecmp_alpha_fold_test(struct kunit *test)
{
	char lower[] = "x";
	char upper[] = "X";
	int i;

	/* Every letter folds to its counterpart, in both argument orders */
	for (i = 0; i < 26; i++) {
		lower[0] = 'a' + i;
		upper[0] = 'A' + i;
		KUNIT_EXPECT_EQ_MSG(test, strncasecmp(lower, upper, 1), 0,
				    "letter %c", lower[0]);
		KUNIT_EXPECT_EQ_MSG(test, strncasecmp(upper, lower, 1), 0,
				    "letter %c", upper[0]);
	}
}

static void strncasecmp_mismatch_test(struct kunit *test)
{
	/* Mismatches return the difference of the lowercased characters */
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "b", 1), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("b", "a", 1), 1);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "B", 1), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("B", "a", 1), 1);
	KUNIT_EXPECT_EQ(test, strncasecmp("A", "c", 1), -2);
	KUNIT_EXPECT_EQ(test, strncasecmp("Z", "a", 1), 25);
	KUNIT_EXPECT_EQ(test, strncasecmp("zz", "ZA", 2), 25);
	KUNIT_EXPECT_EQ(test, strncasecmp("ABD", "abc", 3), 1);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABD", 3), -1);
}

static void strncasecmp_length_boundary_test(struct kunit *test)
{
	/* The mismatch at index 2 is seen with len 3 and hidden with len 2 */
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abd", 3), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abd", 2), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abd", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abd", "abc", 3), 1);
	KUNIT_EXPECT_EQ(test, strncasecmp("abd", "abc", 2), 0);
}

static void strncasecmp_terminator_test(struct kunit *test)
{
	/* Hitting a NUL in one string stops the scan; the result is the raw byte difference */
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abcd", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abcd", 4), -100);
	KUNIT_EXPECT_EQ(test, strncasecmp("abcd", "abc", 4), 100);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ab", 5), 99);
	KUNIT_EXPECT_EQ(test, strncasecmp("ABC", "ab", 5), 67);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab", "ABC", 5), -67);
}

static void strncasecmp_empty_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "a", 1), -97);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "", 1), 97);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "A", 1), -65);
}

static void strncasecmp_non_alpha_test(struct kunit *test)
{
	/* These pairs differ only in bit 0x20; non-letters must not fold */
	KUNIT_EXPECT_EQ(test, strncasecmp("[", "{", 1), -32);
	KUNIT_EXPECT_EQ(test, strncasecmp("@", "`", 1), -32);
	KUNIT_EXPECT_EQ(test, strncasecmp("\x01", "\x21", 1), -32);
	KUNIT_EXPECT_EQ(test, strncasecmp("@", "@", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("1", "1", 1), 0);
}

static void strncasecmp_high_byte_test(struct kunit *test)
{
	/* Bytes are compared as unsigned char */
	KUNIT_EXPECT_GT(test, strncasecmp("\x80", "\x7f", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("\x7f", "\x80", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("\xc1", "\xc2", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("\xff", "\xff", 1), 0);
}

static void strncasecmp_exact_buffer_test(struct kunit *test)
{
	char *a = kunit_kmalloc(test, 3, GFP_KERNEL);
	char *b = kunit_kmalloc(test, 3, GFP_KERNEL);

	KUNIT_ASSERT_NOT_NULL(test, a);
	KUNIT_ASSERT_NOT_NULL(test, b);

	/* No terminator: the function must stop after exactly len bytes */
	memcpy(a, "abc", 3);
	memcpy(b, "ABC", 3);
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 2), 0);

	b[2] = 'D';
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 3), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 2), 0);
}

static void strncasecmp_position_sweep_test(struct kunit *test)
{
	char s1[] = "aaaaaaaa";
	char s2[9];
	int pos, len;

	/* A single mismatch at pos is visible exactly when len > pos */
	for (pos = 0; pos < 8; pos++) {
		memcpy(s2, "AAAAAAAA", sizeof(s2));
		s2[pos] = 'b';
		for (len = 1; len <= 8; len++) {
			KUNIT_EXPECT_EQ_MSG(test, strncasecmp(s1, s2, len),
					    len > pos ? -1 : 0,
					    "pos %d len %d", pos, len);
		}
	}
}

static void strncasecmp_antisymmetry_test(struct kunit *test)
{
	static const char *const strs[] = {
		"", "a", "A", "abc", "ABD", "abd", "Zebra", "zebra", "\x80", "[",
	};
	size_t i, j;
	int ab, ba;

	for (i = 0; i < ARRAY_SIZE(strs); i++) {
		for (j = 0; j < ARRAY_SIZE(strs); j++) {
			ab = strncasecmp(strs[i], strs[j], 8);
			ba = strncasecmp(strs[j], strs[i], 8);
			KUNIT_EXPECT_EQ_MSG(test, (ab > 0) - (ab < 0),
					    -((ba > 0) - (ba < 0)),
					    "\"%s\" vs \"%s\"", strs[i], strs[j]);
		}
	}
}

static struct kunit_case agent_strncasecmp_cases[] = {
	KUNIT_CASE(strncasecmp_zero_len_test),
	KUNIT_CASE(strncasecmp_equal_test),
	KUNIT_CASE(strncasecmp_alpha_fold_test),
	KUNIT_CASE(strncasecmp_mismatch_test),
	KUNIT_CASE(strncasecmp_length_boundary_test),
	KUNIT_CASE(strncasecmp_terminator_test),
	KUNIT_CASE(strncasecmp_empty_test),
	KUNIT_CASE(strncasecmp_non_alpha_test),
	KUNIT_CASE(strncasecmp_high_byte_test),
	KUNIT_CASE(strncasecmp_exact_buffer_test),
	KUNIT_CASE(strncasecmp_position_sweep_test),
	KUNIT_CASE(strncasecmp_antisymmetry_test),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_strncasecmp_cases,
};

kunit_test_suite(agent_test_suite);

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */

#include <kunit/test.h>
#include <linux/slab.h>
#include <linux/string.h>

/*
 * strcspn() returns the length of the initial segment of @s that contains
 * no byte from @reject. Each case below pins down an exact count, so an
 * off-by-one or a wrong comparison changes the result.
 */

static void strcspn_empty_string_returns_zero(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("", "abc"), (size_t)0);
}

static void strcspn_empty_reject_returns_full_length(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", ""), (size_t)6);
}

static void strcspn_both_empty_returns_zero(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("", ""), (size_t)0);
}

static void strcspn_match_at_first_char(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", "a"), (size_t)0);
}

static void strcspn_match_at_last_char(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", "c"), (size_t)2);
}

static void strcspn_match_in_middle(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "d"), (size_t)3);
}

static void strcspn_no_match_returns_length(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "xyz"), (size_t)6);
}

static void strcspn_single_char_match(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("a", "a"), (size_t)0);
}

static void strcspn_single_char_no_match(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("a", "b"), (size_t)1);
}

static void strcspn_equal_strings_return_zero(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", "abc"), (size_t)0);
}

static void strcspn_returns_first_occurrence_of_any_reject_char(struct kunit *test)
{
	/* 'd' appears at index 3 and 'f' at index 5; the earlier one wins. */
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "fd"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "fa"), (size_t)0);
}

static void strcspn_reject_order_is_irrelevant(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "oe"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "eo"), (size_t)1);
}

static void strcspn_repeated_reject_chars(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcabc", "bbbb"), (size_t)1);
}

static void strcspn_repeated_string_chars_stop_at_first(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("aaaa", "a"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("bbba", "a"), (size_t)3);
}

static void strcspn_is_case_sensitive(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcABC", "A"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("abc", "A"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("abcABC", "a"), (size_t)0);
}

static void strcspn_stops_at_string_nul(struct kunit *test)
{
	/* The bytes after the embedded NUL are not part of the string. */
	KUNIT_EXPECT_EQ(test, strcspn("ab\0cd", "cd"), (size_t)2);
}

static void strcspn_reject_nul_terminates_reject_set(struct kunit *test)
{
	/* Only "c" is in the reject set; the 'd' after the NUL is not. */
	KUNIT_EXPECT_EQ(test, strcspn("xyd", "c\0d"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("xyc", "c\0d"), (size_t)2);
}

static void strcspn_high_bit_bytes(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("\x80\xff", "\xff"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("\x80\xff", "\x80"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("\x80\xff", "\x7f"), (size_t)2);
}

static void strcspn_whitespace_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("foo bar", " \t"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("  \tx", " \t"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("x\n", " \t\n"), (size_t)1);
}

static void strcspn_path_separator(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("/usr/lib/x", "/"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("usr/lib", "/"), (size_t)3);
}

static void strcspn_key_value_split(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("key=value", "="), (size_t)3);
}

static void strcspn_digits_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("0123456789", "0123456789"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("abc XYZ", "0123456789"), (size_t)7);
}

static void strcspn_reject_longer_than_string(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("ab", "xyzw"), (size_t)2);
}

static void strcspn_reject_partially_overlaps_string(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", "bc"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("ab", "xabc"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("abc", "ab"), (size_t)0);
}

static void strcspn_match_only_at_end(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcdz", "z"), (size_t)4);
}

static void strcspn_every_match_position(struct kunit *test)
{
	const size_t len = 64;
	char *buf = kunit_kmalloc(test, len, GFP_KERNEL);
	size_t i;

	KUNIT_ASSERT_NOT_NULL(test, buf);

	/* Put a single 'Z' at each position and check the exact index. */
	memset(buf, 'a', len - 1);
	buf[len - 1] = '\0';
	for (i = 0; i < len - 1; i++) {
		buf[i] = 'Z';
		KUNIT_EXPECT_EQ_MSG(test, strcspn(buf, "Z"), i, "pos=%zu", i);
		buf[i] = 'a';
	}
}

static void strcspn_long_string_no_match(struct kunit *test)
{
	const size_t len = 1024;
	char *buf = kunit_kmalloc(test, len + 1, GFP_KERNEL);

	KUNIT_ASSERT_NOT_NULL(test, buf);

	memset(buf, 'a', len);
	buf[len] = '\0';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), len);
}

static void strcspn_long_string_match_at_end(struct kunit *test)
{
	const size_t len = 1000;
	char *buf = kunit_kmalloc(test, len + 1, GFP_KERNEL);

	KUNIT_ASSERT_NOT_NULL(test, buf);

	memset(buf, 'a', len);
	buf[len - 1] = 'b';
	buf[len] = '\0';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), len - 1);
}

static void strcspn_long_reject_set(struct kunit *test)
{
	/*
	 * Every byte from 0x01 to 0x7f is in the reject set except 'q'.
	 * The two high-bit bytes and 'q' are not rejected, so the scan
	 * runs past them and stops at 'z'.
	 */
	char reject[128];
	size_t i, n = 0;

	for (i = 1; i < 0x80; i++)
		if (i != 'q')
			reject[n++] = (char)i;
	reject[n] = '\0';

	KUNIT_EXPECT_EQ(test, strcspn("\x80\x81qz", reject), (size_t)3);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(strcspn_empty_string_returns_zero),
	KUNIT_CASE(strcspn_empty_reject_returns_full_length),
	KUNIT_CASE(strcspn_both_empty_returns_zero),
	KUNIT_CASE(strcspn_match_at_first_char),
	KUNIT_CASE(strcspn_match_at_last_char),
	KUNIT_CASE(strcspn_match_in_middle),
	KUNIT_CASE(strcspn_no_match_returns_length),
	KUNIT_CASE(strcspn_single_char_match),
	KUNIT_CASE(strcspn_single_char_no_match),
	KUNIT_CASE(strcspn_equal_strings_return_zero),
	KUNIT_CASE(strcspn_returns_first_occurrence_of_any_reject_char),
	KUNIT_CASE(strcspn_reject_order_is_irrelevant),
	KUNIT_CASE(strcspn_repeated_reject_chars),
	KUNIT_CASE(strcspn_repeated_string_chars_stop_at_first),
	KUNIT_CASE(strcspn_is_case_sensitive),
	KUNIT_CASE(strcspn_stops_at_string_nul),
	KUNIT_CASE(strcspn_reject_nul_terminates_reject_set),
	KUNIT_CASE(strcspn_high_bit_bytes),
	KUNIT_CASE(strcspn_whitespace_reject),
	KUNIT_CASE(strcspn_path_separator),
	KUNIT_CASE(strcspn_key_value_split),
	KUNIT_CASE(strcspn_digits_reject),
	KUNIT_CASE(strcspn_reject_longer_than_string),
	KUNIT_CASE(strcspn_reject_partially_overlaps_string),
	KUNIT_CASE(strcspn_match_only_at_end),
	KUNIT_CASE(strcspn_every_match_position),
	KUNIT_CASE(strcspn_long_string_no_match),
	KUNIT_CASE(strcspn_long_string_match_at_end),
	KUNIT_CASE(strcspn_long_reject_set),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/limits.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

/*
 * Format @size/@blk and compare against @exp. The return value must be the
 * length of the full output, which is the same as strlen(@exp).
 */
static void check_size(struct kunit *test, u64 size, u64 blk,
		       unsigned int units, const char *exp)
{
	char buf[32];
	int ret;

	ret = string_get_size(size, blk, units, buf, sizeof(buf));
	KUNIT_EXPECT_STREQ_MSG(test, buf, exp,
			       "size=%llu blk=%llu units=%#x",
			       size, blk, units);
	KUNIT_EXPECT_EQ_MSG(test, ret, (int)strlen(exp),
			    "size=%llu blk=%llu units=%#x",
			    size, blk, units);
}

static void test_zero_size(struct kunit *test)
{
	check_size(test, 0, 1, STRING_UNITS_10, "0 B");
	check_size(test, 0, 1, STRING_UNITS_2, "0 B");
	check_size(test, 0, 512, STRING_UNITS_2, "0 B");
	check_size(test, 0, U64_MAX, STRING_UNITS_10, "0 B");
}

static void test_zero_block_size(struct kunit *test)
{
	/* blk_size == 0 forces the size to zero */
	check_size(test, 12345, 0, STRING_UNITS_10, "0 B");
	check_size(test, 12345, 0, STRING_UNITS_2, "0 B");
	check_size(test, U64_MAX, 0, STRING_UNITS_2, "0 B");
}

static void test_bytes_small(struct kunit *test)
{
	/* Under 10 is printed with two decimals, under 100 with one */
	check_size(test, 1, 1, STRING_UNITS_10, "1.00 B");
	check_size(test, 9, 1, STRING_UNITS_10, "9.00 B");
	check_size(test, 10, 1, STRING_UNITS_10, "10.0 B");
	check_size(test, 12, 1, STRING_UNITS_10, "12.0 B");
	check_size(test, 99, 1, STRING_UNITS_10, "99.0 B");
	check_size(test, 100, 1, STRING_UNITS_10, "100 B");
	check_size(test, 123, 1, STRING_UNITS_10, "123 B");
	check_size(test, 512, 1, STRING_UNITS_2, "512 B");
}

static void test_decimal_unit_boundaries(struct kunit *test)
{
	check_size(test, 999, 1, STRING_UNITS_10, "999 B");
	check_size(test, 1000, 1, STRING_UNITS_10, "1.00 kB");
	check_size(test, 1001, 1, STRING_UNITS_10, "1.00 kB");
	check_size(test, 1000000, 1, STRING_UNITS_10, "1.00 MB");
	check_size(test, 1000000000ULL, 1, STRING_UNITS_10, "1.00 GB");
	check_size(test, 1000000000000ULL, 1, STRING_UNITS_10, "1.00 TB");
	check_size(test, 1000000000000000ULL, 1, STRING_UNITS_10, "1.00 PB");
	check_size(test, 1000000000000000000ULL, 1, STRING_UNITS_10, "1.00 EB");
}

static void test_binary_unit_boundaries(struct kunit *test)
{
	check_size(test, 1023, 1, STRING_UNITS_2, "1023 B");
	check_size(test, 1024, 1, STRING_UNITS_2, "1.00 KiB");
	check_size(test, 1025, 1, STRING_UNITS_2, "1.00 KiB");
	check_size(test, 1ULL << 20, 1, STRING_UNITS_2, "1.00 MiB");
	check_size(test, 1ULL << 30, 1, STRING_UNITS_2, "1.00 GiB");
	check_size(test, 1ULL << 40, 1, STRING_UNITS_2, "1.00 TiB");
	check_size(test, 1ULL << 50, 1, STRING_UNITS_2, "1.00 PiB");
	check_size(test, 1ULL << 60, 1, STRING_UNITS_2, "1.00 EiB");
}

static void test_decimal_rounding(struct kunit *test)
{
	/* 3 significant figures, rounded half up */
	check_size(test, 1004, 1, STRING_UNITS_10, "1.00 kB");
	check_size(test, 1005, 1, STRING_UNITS_10, "1.01 kB");
	check_size(test, 1014, 1, STRING_UNITS_10, "1.01 kB");
	check_size(test, 1100, 1, STRING_UNITS_10, "1.10 kB");
	check_size(test, 1500, 1, STRING_UNITS_10, "1.50 kB");
	check_size(test, 1994, 1, STRING_UNITS_10, "1.99 kB");
	check_size(test, 1995, 1, STRING_UNITS_10, "2.00 kB");
	check_size(test, 15540, 1, STRING_UNITS_10, "15.5 kB");
	check_size(test, 15550, 1, STRING_UNITS_10, "15.6 kB");
}

static void test_binary_rounding(struct kunit *test)
{
	check_size(test, 1036, 1, STRING_UNITS_2, "1.01 KiB");
	check_size(test, 1060, 1, STRING_UNITS_2, "1.04 KiB");
	check_size(test, 1075, 1, STRING_UNITS_2, "1.05 KiB");
	check_size(test, 1536, 1, STRING_UNITS_2, "1.50 KiB");
	check_size(test, 1047552, 1, STRING_UNITS_2, "1023 KiB");
}

static void test_digit_precision(struct kunit *test)
{
	/* Number of decimals depends on the integer part: 1, 2 or 3 digits */
	check_size(test, 10000, 1, STRING_UNITS_10, "10.0 kB");
	check_size(test, 100000, 1, STRING_UNITS_10, "100 kB");
	check_size(test, 10240, 1, STRING_UNITS_2, "10.0 KiB");
	check_size(test, 102400, 1, STRING_UNITS_2, "100 KiB");
	check_size(test, 99950, 1, STRING_UNITS_10, "100.0 kB");
}

static void test_block_size_scaling(struct kunit *test)
{
	check_size(test, 1, 1024, STRING_UNITS_2, "1.00 KiB");
	check_size(test, 2, 512, STRING_UNITS_2, "1.00 KiB");
	check_size(test, 3, 1000, STRING_UNITS_10, "3.00 kB");
	check_size(test, 1, 1000, STRING_UNITS_10, "1.00 kB");
	check_size(test, 4096, 4096, STRING_UNITS_2, "16.0 MiB");
	check_size(test, 1, 1ULL << 40, STRING_UNITS_2, "1.00 TiB");
	check_size(test, 1, 1ULL << 32, STRING_UNITS_2, "4.00 GiB");
}

static void test_reference_values(struct kunit *test)
{
	check_size(test, 16384, 512, STRING_UNITS_10, "8.39 MB");
	check_size(test, 16384, 512, STRING_UNITS_2, "8.00 MiB");
	check_size(test, 500118192, 512, STRING_UNITS_10, "256 GB");
	check_size(test, 500118192, 512, STRING_UNITS_2, "238 GiB");
	check_size(test, 8192, 4096, STRING_UNITS_10, "33.6 MB");
	check_size(test, 8192, 4096, STRING_UNITS_2, "32.0 MiB");
	check_size(test, 3000, 1900, STRING_UNITS_10, "5.70 MB");
	check_size(test, 3000, 1900, STRING_UNITS_2, "5.44 MiB");
	check_size(test, 1100, 1, STRING_UNITS_10, "1.10 kB");
	check_size(test, 1100, 1, STRING_UNITS_2, "1.07 KiB");
}

static void test_large_values(struct kunit *test)
{
	/* 2^64 - 1 is 18.4467... EB and 15.9999... EiB */
	check_size(test, U64_MAX, 1, STRING_UNITS_10, "18.4 EB");
	check_size(test, U64_MAX, 1, STRING_UNITS_2, "16.0 EiB");
	/* Product of two 32-bit values, no 64-bit overflow */
	check_size(test, U32_MAX, U32_MAX, STRING_UNITS_10, "18.4 EB");
	check_size(test, 1ULL << 32, 1, STRING_UNITS_2, "4.00 GiB");
	check_size(test, U32_MAX, 1, STRING_UNITS_2, "4.00 GiB");
}

static void test_unknown_unit(struct kunit *test)
{
	/* 1e36 bytes needs 12 scaling steps, beyond units_2[] */
	check_size(test, 1000000000000000000ULL, 1000000000000000000ULL,
