/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/kernel.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define GUARD_BYTE 'G'

/*
 * Escape @isz bytes of @src into a guarded buffer and check the return value,
 * the output bytes, and that no NUL terminator was written past the output.
 */
static void check_escape(struct kunit *test, const char *src, size_t isz,
			 unsigned int flags, const char *only,
			 const char *exp, size_t explen)
{
	char buf[64];
	int ret;

	memset(buf, GUARD_BYTE, sizeof(buf));
	ret = string_escape_mem(src, isz, buf, sizeof(buf), flags, only);

	KUNIT_EXPECT_EQ(test, ret, (int)explen);
	KUNIT_EXPECT_MEMEQ(test, buf, exp, explen);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[explen], GUARD_BYTE);
}

#define CHECK_ESC(test, src, flags, only, exp)				\
	check_escape((test), (src), sizeof(src) - 1, (flags), (only),	\
		     (exp), sizeof(exp) - 1)

/*
 * For every osz from 0 to past the end of the full output, the return value
 * must be the full length, the written prefix must match, and nothing at or
 * beyond osz may be touched.
 */
static void check_truncation(struct kunit *test, const char *src, size_t isz,
			     unsigned int flags, const char *exp, size_t explen)
{
	char buf[64];
	size_t osz, i;
	int ret;

	for (osz = 0; osz <= explen + 2; osz++) {
		memset(buf, GUARD_BYTE, sizeof(buf));
		ret = string_escape_mem(src, isz, buf, osz, flags, NULL);

		KUNIT_EXPECT_EQ_MSG(test, ret, (int)explen, "osz=%zu", osz);
		for (i = 0; i < sizeof(buf); i++) {
			if (i < osz && i < explen)
				KUNIT_EXPECT_EQ_MSG(test, buf[i], exp[i],
						    "osz=%zu i=%zu", osz, i);
			else
				KUNIT_EXPECT_EQ_MSG(test, (unsigned char)buf[i],
						    GUARD_BYTE,
						    "osz=%zu i=%zu", osz, i);
		}
	}
}

#define CHECK_TRUNC(test, src, flags, exp)				\
	check_truncation((test), (src), sizeof(src) - 1, (flags),	\
			 (exp), sizeof(exp) - 1)

static void agent_zero_length_input(struct kunit *test)
{
	char buf[8];

	memset(buf, GUARD_BYTE, sizeof(buf));
	KUNIT_EXPECT_EQ(test, string_escape_mem("abc", 0, buf, sizeof(buf),
						ESCAPE_ANY, NULL), 0);
	KUNIT_EXPECT_EQ(test, string_escape_mem("abc", 0, NULL, 0,
						ESCAPE_ANY, NULL), 0);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[0], GUARD_BYTE);
}

static void agent_input_size_limits_read(struct kunit *test)
{
	/* isz, not strlen(), decides how many input bytes are consumed. */
	check_escape(test, "abc", 2, 0, NULL, "ab", 2);
	check_escape(test, "abc", 1, 0, NULL, "a", 1);
	check_escape(test, "abc", 3, 0, NULL, "abc", 3);
}

static void agent_no_flags_passthrough(struct kunit *test)
{
	char src[256], out[512], exp[256];
	int i, ret;

	for (i = 0; i < 256; i++)
		src[i] = exp[i] = (char)i;

	memset(out, GUARD_BYTE, sizeof(out));
	ret = string_escape_mem(src, sizeof(src), out, sizeof(out), 0, NULL);
	KUNIT_EXPECT_EQ(test, ret, 256);
	KUNIT_EXPECT_MEMEQ(test, out, exp, sizeof(exp));
}

static void agent_null_dst_returns_length(struct kunit *test)
{
	/* A zero-sized destination must still report the full length. */
	KUNIT_EXPECT_EQ(test, string_escape_mem("abc", 3, NULL, 0, 0, NULL), 3);
	KUNIT_EXPECT_EQ(test, string_escape_mem("abc", 3, NULL, 0,
						ESCAPE_OCTAL, NULL), 12);
	KUNIT_EXPECT_EQ(test, string_escape_mem("\x01", 1, NULL, 0,
						ESCAPE_HEX, NULL), 4);
}

static void agent_space_escapes(struct kunit *test)
{
	CHECK_ESC(test, "\n\r\t\v\f", ESCAPE_SPACE, NULL, "\\n\\r\\t\\v\\f");
	CHECK_ESC(test, "\n", ESCAPE_SPACE, NULL, "\\n");
	CHECK_ESC(test, "\f", ESCAPE_SPACE, NULL, "\\f");
}

static void agent_space_leaves_other_chars(struct kunit *test)
{
	/* Plain space is not in the ESCAPE_SPACE class. */
	CHECK_ESC(test, " ", ESCAPE_SPACE, NULL, " ");
	CHECK_ESC(test, "\x01\x7f\x00z", ESCAPE_SPACE, NULL, "\x01\x7f\x00z");
	CHECK_ESC(test, "\x1b\a", ESCAPE_SPACE, NULL, "\x1b\a");
}

static void agent_special_escapes(struct kunit *test)
{
	CHECK_ESC(test, "\\", ESCAPE_SPECIAL, NULL, "\\\\");
	CHECK_ESC(test, "\"", ESCAPE_SPECIAL, NULL, "\\\"");
	CHECK_ESC(test, "\\\"", ESCAPE_SPECIAL, NULL, "\\\\\\\"");
}

static void agent_special_bel_esc_apostrophe(struct kunit *test)
{
	CHECK_ESC(test, "\a", ESCAPE_SPECIAL, NULL, "\\a");
	CHECK_ESC(test, "\x1b", ESCAPE_SPECIAL, NULL, "\\e");
	/* Apostrophe is not in the ESCAPE_SPECIAL class. */
	CHECK_ESC(test, "'", ESCAPE_SPECIAL, NULL, "'");
}

static void agent_null_escape(struct kunit *test)
{
	CHECK_ESC(test, "\0", ESCAPE_NULL, NULL, "\\0");
	/* Embedded NULs are consumed by length, not treated as terminators. */
	CHECK_ESC(test, "a\0b", ESCAPE_NULL, NULL, "a\\0b");
	CHECK_ESC(test, "\x01", ESCAPE_NULL, NULL, "\x01");
}

static void agent_null_before_octal(struct kunit *test)
{
	/* NUL goes to the NULL class, not to a three-digit octal escape. */
	CHECK_ESC(test, "\0", ESCAPE_NULL | ESCAPE_OCTAL, NULL, "\\0");
	CHECK_ESC(test, "\0", ESCAPE_OCTAL, NULL, "\\000");
}

static void agent_octal_values(struct kunit *test)
{
	CHECK_ESC(test, "\x01", ESCAPE_OCTAL, NULL, "\\001");
	CHECK_ESC(test, "\x7f", ESCAPE_OCTAL, NULL, "\\177");
	CHECK_ESC(test, "\x80", ESCAPE_OCTAL, NULL, "\\200");
	CHECK_ESC(test, "\xc5", ESCAPE_OCTAL, NULL, "\\305");
	CHECK_ESC(test, "\xff", ESCAPE_OCTAL, NULL, "\\377");
	CHECK_ESC(test, "\x08", ESCAPE_OCTAL, NULL, "\\010");
}

static void agent_octal_exhaustive(struct kunit *test)
{
	static char src[256], exp[256 * 4], out[256 * 4 + 8];
	char tmp[8];
	size_t i, n = 0;
	int ret;

	for (i = 0; i < 256; i++) {
		src[i] = (char)i;
		snprintf(tmp, sizeof(tmp), "\\%03o", (unsigned int)i);
		memcpy(exp + n, tmp, 4);
		n += 4;
	}

	memset(out, GUARD_BYTE, sizeof(out));
	ret = string_escape_mem(src, sizeof(src), out, sizeof(out),
				ESCAPE_OCTAL, NULL);
	KUNIT_EXPECT_EQ(test, ret, (int)n);
	KUNIT_EXPECT_MEMEQ(test, out, exp, n);
}

static void agent_hex_escapes(struct kunit *test)
{
	CHECK_ESC(test, "\x00", ESCAPE_HEX, NULL, "\\x00");
	CHECK_ESC(test, "\x0a", ESCAPE_HEX, NULL, "\\x0a");
	CHECK_ESC(test, "\xab", ESCAPE_HEX, NULL, "\\xab");
	CHECK_ESC(test, "\xff", ESCAPE_HEX, NULL, "\\xff");
	CHECK_ESC(test, "\x7f", ESCAPE_HEX, NULL, "\\x7f");
}

static void agent_hex_exhaustive(struct kunit *test)
{
	static const char hex[] = "0123456789abcdef";
	static char src[256], exp[256 * 4], out[256 * 4 + 8];
	size_t i, n = 0;
	int ret;

	for (i = 0; i < 256; i++) {
		src[i] = (char)i;
		exp[n++] = '\\';
		exp[n++] = 'x';
		exp[n++] = hex[i >> 4];
		exp[n++] = hex[i & 0xf];
	}

	memset(out, GUARD_BYTE, sizeof(out));
	ret = string_escape_mem(src, sizeof(src), out, sizeof(out),
				ESCAPE_HEX, NULL);
	KUNIT_EXPECT_EQ(test, ret, (int)n);
	KUNIT_EXPECT_MEMEQ(test, out, exp, n);
}

static void agent_octal_wins_over_hex(struct kunit *test)
{
	/* ESCAPE_OCTAL is tried before ESCAPE_HEX, so it takes precedence. */
	CHECK_ESC(test, "\x01", ESCAPE_OCTAL | ESCAPE_HEX, NULL, "\\001");
}

static void agent_space_wins_over_octal(struct kunit *test)
{
	CHECK_ESC(test, "\n\x01", ESCAPE_SPACE | ESCAPE_OCTAL, NULL,
		  "\\n\\001");
}

static void agent_special_wins_over_octal(struct kunit *test)
{
	CHECK_ESC(test, "\\\"\a", ESCAPE_SPECIAL | ESCAPE_OCTAL, NULL,
		  "\\\\\\\"\\a");
}

static void agent_any_flag(struct kunit *test)
{
	/* OCTAL is the last class and escapes any byte that reaches it. */
	CHECK_ESC(test, "\n\"\0\x7fz", ESCAPE_ANY, NULL,
		  "\\n\\\"\\0\\177\\172");
	/* NP passes printable bytes ('"' and 'z') through before the classes. */
	CHECK_ESC(test, "\n\"\0\x7fz", ESCAPE_ANY_NP, NULL,
		  "\\n\"\\0\\177z");
	CHECK_ESC(test, "a b~", ESCAPE_ANY_NP, NULL, "a b~");
}

static void agent_np_escapes_nonprintable(struct kunit *test)
{
	/*
	 * The kernel's isprint() is Latin-1 aware: 0xa0-0xff are printable,
	 * while 0x7f and 0x80-0x9f are not.
	 */
	CHECK_ESC(test, "a\x01~\x7f\x80\xa9", ESCAPE_NP | ESCAPE_OCTAL, NULL,
		  "a\\001~\\177\\200\xa9");
	/* Without a formatting class NP only passes printable bytes through. */
	CHECK_ESC(test, "\x01\x80", ESCAPE_NP, NULL, "\x01\x80");
}

static void agent_na_escapes_nonascii(struct kunit *test)
{
	CHECK_ESC(test, "a\xc3\xa9", ESCAPE_NA | ESCAPE_OCTAL, NULL,
		  "a\\303\\251");
	/* ASCII control characters are not escaped by NA. */
	CHECK_ESC(test, "\x01\x7f", ESCAPE_NA | ESCAPE_OCTAL, NULL,
		  "\x01\x7f");
}

static void agent_na_alone_passthrough(struct kunit *test)
{
	/* Without a formatting class, NA passes everything through. */
	CHECK_ESC(test, "\x01\xc3\xa9", ESCAPE_NA, NULL, "\x01\xc3\xa9");
}

static void agent_nap_escapes(struct kunit *test)
{
	CHECK_ESC(test, "a\n\x01\x7f\x80 ", ESCAPE_NAP | ESCAPE_SPACE |
		  ESCAPE_OCTAL, NULL, "a\\n\\001\\177\\200 ");
	CHECK_ESC(test, "a\n\x01\x7f\x80 ", ESCAPE_NAP | ESCAPE_OCTAL, NULL,
		  "a\\012\\001\\177\\200 ");
}

static void agent_only_limits_escape(struct kunit *test)
{
	/* With @only set, only characters listed in it are escaped. */
	CHECK_ESC(test, "a\nb", ESCAPE_OCTAL, "\n", "a\\012b");
	CHECK_ESC(test, "\\\"", ESCAPE_SPECIAL, "\"", "\\\\\"");
}

static void agent_only_leaves_unlisted_chars(struct kunit *test)
{
	CHECK_ESC(test, "\n", ESCAPE_SPACE, "x", "\n");
	CHECK_ESC(test, "\x01", ESCAPE_OCTAL, "x", "\x01");
}

static void agent_only_empty_or_null_escapes_all(struct kunit *test)
{
	CHECK_ESC(test, "a\n", ESCAPE_SPACE, "", "a\\n");
	CHECK_ESC(test, "a\n", ESCAPE_SPACE, NULL, "a\\n");
}

static void agent_append_escapes_listed_chars(struct kunit *test)
{
	/* APPEND makes listed characters escapable by the NP class. */
	CHECK_ESC(test, "abc ", ESCAPE_NP | ESCAPE_OCTAL | ESCAPE_APPEND,
		  "a", "\\141bc ");
}

static void agent_append_off_keeps_listed_chars(struct kunit *test)
{
	/* Without APPEND, printable listed characters pass through NP. */
	CHECK_ESC(test, "abc ", ESCAPE_NP | ESCAPE_OCTAL, "a", "abc ");
}

static void agent_truncation_every_osz(struct kunit *test)
{
	CHECK_TRUNC(test, "abc", 0, "abc");
	CHECK_TRUNC(test, "a\n\\", ESCAPE_SPACE | ESCAPE_SPECIAL,
		    "a\\n\\\\");
	CHECK_TRUNC(test, "\x01\xff", ESCAPE_OCTAL, "\\001\\377");
	CHECK_TRUNC(test, "\x1f", ESCAPE_HEX, "\\x1f");
	CHECK_TRUNC(test, "\0", ESCAPE_NULL, "\\0");
}

static void agent_truncation_partial_escape(struct kunit *test)
{
	char buf[16];
	int ret;

	/* Octal escape cut after one, two and three output bytes. */
	memset(buf, GUARD_BYTE, sizeof(buf));
	ret = string_escape_mem("\x01", 1, buf, 1, ESCAPE_OCTAL, NULL);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_EQ(test, buf[0], '\\');
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[1], GUARD_BYTE);

	memset(buf, GUARD_BYTE, sizeof(buf));
	ret = string_escape_mem("\x01", 1, buf, 3, ESCAPE_OCTAL, NULL);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_MEMEQ(test, buf, "\\00", 3);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[3], GUARD_BYTE);

	/* Exactly full: no room for a NUL terminator, and none is written. */
	memset(buf, GUARD_BYTE, sizeof(buf));
	ret = string_escape_mem("\x01", 1, buf, 4, ESCAPE_OCTAL, NULL);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_MEMEQ(test, buf, "\\001", 4);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[4], GUARD_BYTE);
}

static void agent_bulk_input(struct kunit *test)
{
	size_t n = 4096, want = n * 4;
	char *src, *dst;
	size_t i;
	int ret;
	bool ok = true;

	src = kunit_kmalloc(test, n, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, src);
	dst = kunit_kmalloc(test, want + 16, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, dst);

	memset(src, 0x01, n);

	/* Exact-fit destination. */
	memset(dst, GUARD_BYTE, want + 16);
	ret = string_escape_mem(src, n, dst, want, ESCAPE_OCTAL, NULL);
	KUNIT_EXPECT_EQ(test, ret, (int)want);
	for (i = 0; i < n; i++)
		if (memcmp(dst + i * 4, "\\001", 4))
			ok = false;
	KUNIT_EXPECT_TRUE(test, ok);
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[want], GUARD_BYTE);

	/* Short destination: full length reported, nothing past osz touched. */
	memset(dst, GUARD_BYTE, want + 16);
	ret = string_escape_mem(src, n, dst, 100, ESCAPE_OCTAL, NULL);
	KUNIT_EXPECT_EQ(test, ret, (int)want);
	KUNIT_EXPECT_MEMEQ(test, dst, "\\001\\001", 8);
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[100], GUARD_BYTE);
	KUNIT_EXPECT_EQ(test, (unsigned char)dst[want + 15], GUARD_BYTE);
}

