#include <kunit/test.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

/*
 * string_unescape() takes a writable, NUL-terminated source, so each case
 * copies its literal input into a local buffer first.
 */
static int unescape_str(struct kunit *test, const char *in, char *dst,
			size_t size, unsigned int flags)
{
	char src[128];

	KUNIT_ASSERT_LT(test, strlen(in), sizeof(src));
	strscpy(src, in, sizeof(src));
	return string_unescape(src, dst, size, flags);
}

static void agent_plain_passthrough(struct kunit *test)
{
	char out[64];
	int ret;

	ret = unescape_str(test, "abc XYZ 123", out, sizeof(out), UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 11);
	KUNIT_EXPECT_STREQ(test, out, "abc XYZ 123");
}

static void agent_empty_input(struct kunit *test)
{
	char out[8] = "junk";
	int ret;

	ret = unescape_str(test, "", out, sizeof(out), UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 0);
	KUNIT_EXPECT_STREQ(test, out, "");
}

static void agent_no_flags_keeps_escapes(struct kunit *test)
{
