	char out[64];
	int ret;

	/* Each escape family must be ignored when its flag is absent. */
	ret = unescape_str(test, "\\n", out, sizeof(out), UNESCAPE_OCTAL |
			   UNESCAPE_HEX | UNESCAPE_SPECIAL);
	KUNIT_EXPECT_EQ(test, ret, 2);
	KUNIT_EXPECT_STREQ(test, out, "\\n");

	ret = unescape_str(test, "\\101", out, sizeof(out), UNESCAPE_SPACE |
			   UNESCAPE_HEX | UNESCAPE_SPECIAL);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_STREQ(test, out, "\\101");

	ret = unescape_str(test, "\\x41", out, sizeof(out), UNESCAPE_SPACE |
			   UNESCAPE_OCTAL | UNESCAPE_SPECIAL);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_STREQ(test, out, "\\x41");

	ret = unescape_str(test, "\\\"", out, sizeof(out), UNESCAPE_SPACE |
			   UNESCAPE_OCTAL | UNESCAPE_HEX);
	KUNIT_EXPECT_EQ(test, ret, 2);
	KUNIT_EXPECT_STREQ(test, out, "\\\"");
}

