	ret = unescape_str(test, "\\n", out, 2, UNESCAPE_SPACE);
	KUNIT_EXPECT_EQ(test, ret, 1);
	KUNIT_EXPECT_STREQ(test, out, "\\");
}

static void agent_size_escape_fits(struct kunit *test)
{
	char out[8];
	int ret;

	ret = unescape_str(test, "\\n", out, 3, UNESCAPE_SPACE);
	KUNIT_EXPECT_EQ(test, ret, 1);
	KUNIT_EXPECT_STREQ(test, out, "\n");
}

/*
 * For every bounded destination size the output must be NUL-terminated, the
 * return value must equal the stored length and fit in size - 1, and it must
 * not exceed the unbounded length. Exact truncation points are not pinned:
 * a truncated escape leaves its backslash raw, so the prefix of the output
 * need not match the unbounded decoding.
 */
static void agent_size_prefix_property(struct kunit *test)
{
	const char *in = "\\x41\\101\\tz\\q\\\"end";
	char full[64];
	char out[64];
	int full_len, ret;
	size_t size;

	full_len = unescape_str(test, in, full, sizeof(full), UNESCAPE_ANY);
	KUNIT_ASSERT_EQ(test, full_len, (int)strlen(full));

	for (size = 1; size <= (size_t)full_len + 2; size++) {
		memset(out, 'X', sizeof(out));
		ret = unescape_str(test, in, out, size, UNESCAPE_ANY);

		KUNIT_EXPECT_LT(test, ret, (int)size);
		KUNIT_EXPECT_EQ(test, out[ret], '\0');
		KUNIT_EXPECT_EQ(test, ret, (int)strlen(out));
		KUNIT_EXPECT_LE(test, ret, full_len);
	}
}

static void agent_no_write_past_size(struct kunit *test)
{
	char buf[16];
	int ret;

	memset(buf, 'X', sizeof(buf));
	ret = unescape_str(test, "abcdefgh", buf, 4, UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 3);
	KUNIT_EXPECT_STREQ(test, buf, "abc");
	KUNIT_EXPECT_EQ(test, buf[4], 'X');
	KUNIT_EXPECT_EQ(test, buf[15], 'X');
}

