 *   0 - no int in string
 *   1 - int found, no subsequent comma
 *   2 - int found including a subsequent comma
 *   3 - hyphen found to denote a range
 */

static void get_option_null_str_pointer(struct kunit *test)
{
	char *str = NULL;
	int val = 99;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 0);
	KUNIT_EXPECT_EQ(test, val, 99);
	KUNIT_EXPECT_PTR_EQ(test, str, (char *)NULL);
}

