	int val = 99;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 0);
	KUNIT_EXPECT_EQ(test, val, 99);
	KUNIT_EXPECT_PTR_EQ(test, str, buf + 0);
}

static void get_option_single_digit(struct kunit *test)
{
	char buf[] = "7";
	char *str = buf;
	int val = -1;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 1);
	KUNIT_EXPECT_EQ(test, val, 7);
	KUNIT_EXPECT_PTR_EQ(test, str, buf + 1);
