/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Covers get_options() from lib/cmdline.c: validation mode (nints == 0),
 * list and range parsing, negative values, slot-count boundaries and
 * the returned end pointer.
 */

#include <kunit/test.h>
#include <linux/string.h>

#define BUF_LEN		8
#define SENTINEL	0x5a5a5a5a

/*
 * Call get_options() on @ints, which has BUF_LEN slots pre-filled with a
 * sentinel. Any slot at or beyond @nints (slot 0 when @nints is 0, since
 * it is the count) that changed means the function wrote out of bounds.
 */
static char *call_get_options(struct kunit *test, const char *str, int nints,
			      int *ints)
{
	char *ret;
	int i;

	for (i = 0; i < BUF_LEN; i++)
		ints[i] = SENTINEL;

	ret = get_options(str, nints, ints);

	for (i = nints ? nints : 1; i < BUF_LEN; i++)
		KUNIT_EXPECT_EQ_MSG(test, ints[i], SENTINEL,
				    "write past nints at index %d", i);

	return ret;
}

/* Validation mode (nints == 0): ints[0] receives the count only. */

static void agent_validate_empty(struct kunit *test)
{
	const char *s = "";
	int ints[BUF_LEN];
	char *ret;

	ret = call_get_options(test, s, 0, ints);
	KUNIT_EXPECT_EQ(test, ints[0], 0);
	KUNIT_EXPECT_PTR_EQ(test, ret, (char *)s);
}

static void agent_validate_single(struct kunit *test)
{
	const char *s = "42";
	int ints[BUF_LEN];
	char *ret;

	ret = call_get_options(test, s, 0, ints);
	KUNIT_EXPECT_EQ(test, ints[0], 1);
	KUNIT_EXPECT_PTR_EQ(test, ret, (char *)s + 2);
}

