// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */

#include <kunit/test.h>
#include <linux/kernel.h>
#include <linux/string.h>

/*
 * Parse @str with memparse() and check both the value and how many bytes
 * were consumed (retptr - str). @consumed is the expected offset of the
 * first unparsed character.
 */
static void expect_memparse(struct kunit *test, const char *str,
			    unsigned long long want, size_t consumed)
{
	char *end = NULL;
	unsigned long long got = memparse(str, &end);

	KUNIT_EXPECT_EQ_MSG(test, got, want, "memparse(\"%s\") value", str);
	KUNIT_EXPECT_EQ_MSG(test, (size_t)(end - str), consumed,
			    "memparse(\"%s\") consumed", str);
}

static void memparse_plain_decimal(struct kunit *test)
{
	expect_memparse(test, "0", 0, 1);
	expect_memparse(test, "1", 1, 1);
	expect_memparse(test, "9", 9, 1);
	expect_memparse(test, "12345", 12345, 5);
}

static void memparse_hex_and_octal_prefixes(struct kunit *test)
{
	expect_memparse(test, "0x10", 16, 4);
	expect_memparse(test, "0X1f", 31, 4);
	expect_memparse(test, "0xff", 255, 4);
	expect_memparse(test, "010", 8, 3);
	expect_memparse(test, "0777", 511, 4);
}

static void memparse_bare_0x_prefix_is_zero(struct kunit *test)
{
	/* No hex digit after "0x": only the leading '0' is parsed. */
	expect_memparse(test, "0xg", 0, 1);
}

static void memparse_empty_and_no_digits(struct kunit *test)
{
	expect_memparse(test, "", 0, 0);
	expect_memparse(test, "x", 0, 0);
	expect_memparse(test, "Mx", 0, 1);
}

static void memparse_suffix_K(struct kunit *test)
{
	expect_memparse(test, "1K", 1ULL << 10, 2);
	expect_memparse(test, "1k", 1ULL << 10, 2);
	expect_memparse(test, "3K", 3ULL << 10, 2);
}

static void memparse_suffix_M(struct kunit *test)
{
	expect_memparse(test, "1M", 1ULL << 20, 2);
	expect_memparse(test, "1m", 1ULL << 20, 2);
	expect_memparse(test, "3M", 3ULL << 20, 2);
}

static void memparse_suffix_G(struct kunit *test)
{
	expect_memparse(test, "1G", 1ULL << 30, 2);
	expect_memparse(test, "1g", 1ULL << 30, 2);
	expect_memparse(test, "3G", 3ULL << 30, 2);
}

static void memparse_suffix_T(struct kunit *test)
{
	expect_memparse(test, "1T", 1ULL << 40, 2);
	expect_memparse(test, "1t", 1ULL << 40, 2);
	expect_memparse(test, "3T", 3ULL << 40, 2);
}

static void memparse_suffix_P(struct kunit *test)
{
	expect_memparse(test, "1P", 1ULL << 50, 2);
	expect_memparse(test, "1p", 1ULL << 50, 2);
	expect_memparse(test, "3P", 3ULL << 50, 2);
}

static void memparse_suffix_E(struct kunit *test)
{
	expect_memparse(test, "1E", 1ULL << 60, 2);
	expect_memparse(test, "1e", 1ULL << 60, 2);
	expect_memparse(test, "15E", 15ULL << 60, 3);
}

static void memparse_suffix_shift_boundaries(struct kunit *test)
{
	/* Largest value that still fits below each unit boundary. */
	expect_memparse(test, "1023K", 1023ULL << 10, 5);
	expect_memparse(test, "1023M", 1023ULL << 20, 5);
	expect_memparse(test, "1023G", 1023ULL << 30, 5);
	expect_memparse(test, "1023T", 1023ULL << 40, 5);
	expect_memparse(test, "1023P", 1023ULL << 50, 5);
	expect_memparse(test, "15E", 15ULL << 60, 3);
	/* 1024 of a unit equals 1 of the next unit. */
	expect_memparse(test, "1024K", 1ULL << 20, 5);
	expect_memparse(test, "1024M", 1ULL << 30, 5);
}

static void memparse_suffix_with_hex_and_octal(struct kunit *test)
{
	expect_memparse(test, "0x10K", 16ULL << 10, 5);
	expect_memparse(test, "0x1000M", 0x1000ULL << 20, 7);
	expect_memparse(test, "010K", 8ULL << 10, 4);
}

static void memparse_stops_at_non_suffix(struct kunit *test)
{
	expect_memparse(test, "10x", 10, 2);
	expect_memparse(test, "1B", 1, 1);
	expect_memparse(test, "1MB", 1ULL << 20, 2);
	expect_memparse(test, "1 K", 1, 1);
	expect_memparse(test, "1,2", 1, 1);
}

static void memparse_suffix_not_repeated(struct kunit *test)
{
	/* Only one suffix is consumed; a second one is left for the caller. */
	expect_memparse(test, "1KK", 1ULL << 10, 2);
	expect_memparse(test, "4Kfoo", 4ULL << 10, 2);
}

static void memparse_suffix_without_digits(struct kunit *test)
{
	/* No digits: value is 0, but a recognised suffix is still consumed. */
	expect_memparse(test, "K", 0, 1);
	expect_memparse(test, "G", 0, 1);
}

static void memparse_negative_not_parsed(struct kunit *test)
{
	/* A leading '-' is not a sign here: nothing is parsed. */
	expect_memparse(test, "-1", 0, 0);
	expect_memparse(test, "-1K", 0, 0);
}

static void memparse_large_values(struct kunit *test)
{
	expect_memparse(test, "4294967296", 1ULL << 32, 10);
	expect_memparse(test, "4294967295K", 4294967295ULL << 10, 11);
	expect_memparse(test, "18446744073709551615", ULLONG_MAX, 20);
}

static void memparse_null_retptr(struct kunit *test)
{
	/* retptr is optional; passing NULL must still return the value. */
	KUNIT_EXPECT_EQ(test, memparse("4K", NULL), 4ULL << 10);
	KUNIT_EXPECT_EQ(test, memparse("2G", NULL), 2ULL << 30);
	KUNIT_EXPECT_EQ(test, memparse("7", NULL), 7ULL);
}

