/* Deterministic pseudo-random bytes (xorshift32). */
static void agent_fill(u8 *buf, size_t len, u32 seed)
{
	u32 x = seed ? seed : 1;
	size_t i;

	for (i = 0; i < len; i++) {
		x ^= x << 13;
		x ^= x >> 17;
		x ^= x << 5;
		buf[i] = (u8)x;
	}
}

static void agent_siphash_known_answer(struct kunit *test)
{
	u8 buf[AGENT_MAX_OFF + 64] __aligned(8);
	size_t off, len, i;

	for (off = 0; off <= AGENT_MAX_OFF; off++) {
		u8 *msg = buf + off;

		for (len = 0; len < ARRAY_SIZE(agent_kat); len++) {
			for (i = 0; i < len; i++)
				msg[i] = (u8)i;
			KUNIT_EXPECT_EQ_MSG(test,
				__siphash_aligned(msg, len, &agent_key),
				agent_kat[len],
				"off=%zu len=%zu", off, len);
		}
	}
}

static void agent_siphash_zero_length(struct kunit *test)
{
	u8 byte = 0xa5;

	/* len == 0 must not read the buffer at all. */
	KUNIT_EXPECT_EQ(test,
			__siphash_aligned(&byte, 0, &agent_key),
			agent_kat[0]);
	KUNIT_EXPECT_EQ(test,
			__siphash_aligned(NULL, 0, &agent_key),
			agent_kat[0]);
}

static void agent_siphash_matches_unaligned(struct kunit *test)
{
	static const size_t big_lens[] = {
		511, 512, 513, 1000, 1023, 1024, 1025, 4095, AGENT_BIG_LEN
	};
	static u8 buf[AGENT_BIG_LEN + AGENT_MAX_OFF + 8] __aligned(8);
	size_t off, len, i;

	/* The unaligned variant is the same algorithm with a different load
	 * path, so any disagreement is a bug in the aligned tail/loop code.
	 */
	for (off = 0; off <= AGENT_MAX_OFF; off++) {
		for (len = 0; len <= AGENT_MAX_LEN; len++) {
			u8 *msg = buf + off;

			agent_fill(msg, len, (u32)(len * 8 + off + 1));
			KUNIT_ASSERT_EQ_MSG(test,
				__siphash_aligned(msg, len, &agent_key),
				__siphash_unaligned(msg, len, &agent_key),
				"off=%zu len=%zu", off, len);
		}
	}

	for (i = 0; i < ARRAY_SIZE(big_lens); i++) {
		u8 *msg = buf + 3;

		len = big_lens[i];
		agent_fill(msg, len, (u32)len);
		KUNIT_EXPECT_EQ_MSG(test,
			__siphash_aligned(msg, len, &agent_key),
			__siphash_unaligned(msg, len, &agent_key),
			"len=%zu", len);
	}
}

static void agent_siphash_specialized_sizes(struct kunit *test)
{
	u8 buf[24] __aligned(8);
	u64 w0, w1, w2;

	agent_fill(buf, sizeof(buf), 0x5eed);
	w0 = get_unaligned_le64(buf);
	w1 = get_unaligned_le64(buf + 8);
	w2 = get_unaligned_le64(buf + 16);

	/* Each of these has a dedicated fixed-size implementation. */
	KUNIT_EXPECT_EQ(test,
			__siphash_aligned(buf, 4, &agent_key),
			siphash_1u32(get_unaligned_le32(buf), &agent_key));
	KUNIT_EXPECT_EQ(test,
			__siphash_aligned(buf, 8, &agent_key),
			siphash_1u64(w0, &agent_key));
	KUNIT_EXPECT_EQ(test,
			__siphash_aligned(buf, 12, &agent_key),
			siphash_3u32(get_unaligned_le32(buf),
				     get_unaligned_le32(buf + 4),
				     get_unaligned_le32(buf + 8),
				     &agent_key));
	KUNIT_EXPECT_EQ(test,
			__siphash_aligned(buf, 16, &agent_key),
			siphash_2u64(w0, w1, &agent_key));
	KUNIT_EXPECT_EQ(test,
			__siphash_aligned(buf, 24, &agent_key),
			siphash_3u64(w0, w1, w2, &agent_key));
}

static void agent_siphash_length_encoded(struct kunit *test)
{
	u8 buf[80] __aligned(8);
	size_t off, len;

	/* The length is folded into the final block, so appending a zero
	 * byte must change the hash even though the data bytes are equal.
	 */
	for (off = 0; off <= AGENT_MAX_OFF; off++) {
		for (len = 0; len < 64; len++) {
			u8 *msg = buf + off;
			u64 h1, h2;

			memset(buf, 0, sizeof(buf));
			agent_fill(msg, len, (u32)(len + 1));
			h1 = __siphash_aligned(msg, len, &agent_key);

			msg[len] = 0;
			h2 = __siphash_aligned(msg, len + 1, &agent_key);
			KUNIT_EXPECT_NE_MSG(test, h1, h2,
				"off=%zu len=%zu", off, len);
		}
	}
}

static void agent_siphash_each_byte_affects_hash(struct kunit *test)
{
	u8 buf[80] __aligned(8);
	size_t len, i;

	/* Flipping any single input byte must change the result. A tail
	 * that drops or mis-masks its last byte fails here at that length.
	 */
	for (len = 1; len <= 70; len++) {
		u64 base;

		agent_fill(buf, len, (u32)len * 77 + 3);
		base = __siphash_aligned(buf, len, &agent_key);
		for (i = 0; i < len; i++) {
			buf[i] ^= 0x01;
			KUNIT_EXPECT_NE_MSG(test, base,
				__siphash_aligned(buf, len, &agent_key),
				"len=%zu byte=%zu", len, i);
			buf[i] ^= 0x01;
		}
	}
}

static void agent_siphash_ignores_trailing_bytes(struct kunit *test)
{
	u8 clean[80] __aligned(8);
	u8 dirty[80] __aligned(8);
	size_t off, len;

	/* Bytes past the end of the message must not leak into the hash:
	 * the tail load may read past it, but must mask those bytes off.
	 */
	for (off = 0; off <= AGENT_MAX_OFF; off++) {
		for (len = 0; len <= 64; len++) {
			u8 *c = clean + off;
			u8 *d = dirty + off;

			memset(clean, 0x00, sizeof(clean));
			memset(dirty, 0xff, sizeof(dirty));
			agent_fill(c, len, (u32)(len * 3 + off + 1));
			memcpy(d, c, len);
			KUNIT_EXPECT_EQ_MSG(test,
				__siphash_aligned(c, len, &agent_key),
				__siphash_aligned(d, len, &agent_key),
				"off=%zu len=%zu", off, len);
		}
	}
}

static void agent_siphash_key_sensitive(struct kunit *test)
{
	/* Slack for the tail load, which may read up to 7 bytes past len. */
	u8 buf[AGENT_MAX_LEN + 8] __aligned(8);
	size_t len;

	/* A one-bit key change must change the result at every length. */
	for (len = 0; len <= AGENT_MAX_LEN; len++) {
		agent_fill(buf, len, (u32)len + 9);
		KUNIT_EXPECT_NE_MSG(test,
			__siphash_aligned(buf, len, &agent_key),
			__siphash_aligned(buf, len, &agent_key_alt),
			"len=%zu", len);
	}
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_siphash_known_answer),
	KUNIT_CASE(agent_siphash_zero_length),
	KUNIT_CASE(agent_siphash_matches_unaligned),
	KUNIT_CASE(agent_siphash_specialized_sizes),
	KUNIT_CASE(agent_siphash_length_encoded),
	KUNIT_CASE(agent_siphash_each_byte_affects_hash),
	KUNIT_CASE(agent_siphash_ignores_trailing_bytes),
	KUNIT_CASE(agent_siphash_key_sensitive),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};

kunit_test_suite(agent_test_suite);

