/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/bitops.h>
#include <linux/kernel.h>
#include <linux/module.h>
#include <linux/siphash.h>
#include <linux/string.h>
#include <linux/types.h>
#include <linux/unaligned.h>

/*
 * __hsiphash_aligned() is only built when the arch lacks efficient unaligned
 * access and BITS_PER_LONG is 64 (see lib/siphash.c). Elsewhere the symbol
 * does not exist, so the suite is compiled out there.
 */
#if BITS_PER_LONG == 64 && !defined(CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS)

#define MAX_LEN 4096

/*
 * Independent SipHash-1-3 reference: byte-at-a-time tail assembly and
 * explicit rounds, so it does not share code paths with lib/siphash.c.
 */
#define REF_SIPROUND(v0, v1, v2, v3) do { \
	v0 += v1; v1 = rol64(v1, 13); v1 ^= v0; v0 = rol64(v0, 32); \
	v2 += v3; v3 = rol64(v3, 16); v3 ^= v2; \
	v0 += v3; v3 = rol64(v3, 21); v3 ^= v0; \
	v2 += v1; v1 = rol64(v1, 17); v1 ^= v2; v2 = rol64(v2, 32); \
} while (0)

static u32 ref_hsiphash(const u8 *data, size_t len, const hsiphash_key_t *key)
{
	u64 v0 = SIPHASH_CONST_0 ^ key->key[0];
	u64 v1 = SIPHASH_CONST_1 ^ key->key[1];
	u64 v2 = SIPHASH_CONST_2 ^ key->key[0];
	u64 v3 = SIPHASH_CONST_3 ^ key->key[1];
	u64 m, b = (u64)len << 56;
	size_t i = 0, j;

	for (; i + sizeof(u64) <= len; i += sizeof(u64)) {
		m = get_unaligned_le64(data + i);
		v3 ^= m;
		REF_SIPROUND(v0, v1, v2, v3);
		v0 ^= m;
	}
	for (j = 0; i + j < len; j++)
		b |= (u64)data[i + j] << (8 * j);

	v3 ^= b;
	REF_SIPROUND(v0, v1, v2, v3);
	v0 ^= b;
	v2 ^= 0xff;
	REF_SIPROUND(v0, v1, v2, v3);
	REF_SIPROUND(v0, v1, v2, v3);
	REF_SIPROUND(v0, v1, v2, v3);
	return (u32)(v0 ^ v1 ^ v2 ^ v3);
}

/* Small deterministic xorshift PRNG so failures are reproducible. */
static u64 next_rand(u64 *s)
{
	*s ^= *s >> 12;
	*s ^= *s << 25;
	*s ^= *s >> 27;
	return *s * 0x2545F4914F6CDD1DULL;
}

static void fill_rand(u64 *s, u8 *buf, size_t n)
{
	size_t i;

	for (i = 0; i < n; i++)
		buf[i] = next_rand(s) & 0xff;
}

static hsiphash_key_t rand_key(u64 *s)
{
	hsiphash_key_t key;

	key.key[0] = next_rand(s);
	key.key[1] = next_rand(s);
	return key;
}

/* kmalloc memory is at least 8-byte aligned, as __hsiphash_aligned() requires. */
static u8 *alloc_buf(struct kunit *test, size_t n)
{
	u8 *buf = kunit_kzalloc(test, n, GFP_KERNEL);

	KUNIT_ASSERT_NOT_NULL(test, buf);
	return buf;
}

static void expect_matches_ref(struct kunit *test, const u8 *data, size_t len,
			       const hsiphash_key_t *key)
{
	KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(data, len, key),
			    ref_hsiphash(data, len, key),
			    "len=%zu", len);
}

static void hsiphash_aligned_empty(struct kunit *test)
{
	u64 rng = 1;
	hsiphash_key_t key = rand_key(&rng);
	u8 *a = alloc_buf(test, 16);
	u8 *b = alloc_buf(test, 16);

	fill_rand(&rng, b, 16);
	/* With len == 0 the input bytes must not influence the result. */
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(a, 0, &key),
			__hsiphash_aligned(b, 0, &key));
	expect_matches_ref(test, a, 0, &key);
}

static void hsiphash_aligned_tail_only(struct kunit *test)
{
	u64 rng = 2;
	int k;
	size_t len;

	for (k = 0; k < 4; k++) {
		hsiphash_key_t key = rand_key(&rng);
		u8 *buf = alloc_buf(test, 8);

		for (len = 1; len < 8; len++) {
			fill_rand(&rng, buf, len);
			expect_matches_ref(test, buf, len, &key);
		}
	}
}

static void hsiphash_aligned_block_boundaries(struct kunit *test)
{
	static const size_t lens[] = { 7, 8, 9, 15, 16, 17, 23, 24, 25, 31, 32, 33 };
	u64 rng = 3;
	size_t i;

	for (i = 0; i < ARRAY_SIZE(lens); i++) {
		hsiphash_key_t key = rand_key(&rng);
		u8 *buf = alloc_buf(test, lens[i]);

		fill_rand(&rng, buf, lens[i]);
		expect_matches_ref(test, buf, lens[i], &key);
	}
}

static void hsiphash_aligned_sweep_small_lengths(struct kunit *test)
{
	u64 rng = 4;
	size_t len;
	int k;

	for (k = 0; k < 2; k++) {
		hsiphash_key_t key = rand_key(&rng);
		u8 *buf = alloc_buf(test, 256);

		for (len = 0; len <= 256; len++) {
			fill_rand(&rng, buf, len);
			expect_matches_ref(test, buf, len, &key);
		}
	}
}

static void hsiphash_aligned_large_lengths(struct kunit *test)
{
	static const size_t lens[] = { 511, 512, 513, 1000, 1001, 1007, 1008,
				       4095, 4096, 4097, 4103 };
	u64 rng = 5;
	size_t i;

	for (i = 0; i < ARRAY_SIZE(lens); i++) {
		hsiphash_key_t key = rand_key(&rng);
		u8 *buf = alloc_buf(test, MAX_LEN + 8);

		fill_rand(&rng, buf, lens[i]);
		expect_matches_ref(test, buf, lens[i], &key);
	}
}

static void hsiphash_aligned_ignores_bytes_past_end(struct kunit *test)
{
	u64 rng = 6;
	hsiphash_key_t key = rand_key(&rng);
	/* Extra slack: the word-at-a-time tail read may touch bytes past len. */
	u8 *base = alloc_buf(test, 128 + 16);
	u8 *a = alloc_buf(test, 128 + 16);
	u8 *b = alloc_buf(test, 128 + 16);
	size_t len;

	fill_rand(&rng, base, 128 + 16);
	for (len = 0; len <= 64; len++) {
		memcpy(a, base, 128 + 16);
		memcpy(b, base, 128 + 16);
		memset(a + len, 0x00, 16);
		memset(b + len, 0xff, 16);

		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(a, len, &key),
				    __hsiphash_aligned(b, len, &key),
				    "len=%zu: bytes past end affect result", len);
		expect_matches_ref(test, base, len, &key);
	}
}

static void hsiphash_aligned_length_is_encoded(struct kunit *test)
{
	hsiphash_key_t key = { { 0x0123456789abcdefUL, 0xfedcba9876543210UL } };
	u8 *buf = alloc_buf(test, 32);
	u32 seen[17];
	size_t len, i;

	/*
	 * All-zero inputs of different lengths differ only in the length
	 * byte and the tail bytes, so each length must hash to its own value.
	 */
	for (len = 0; len <= 16; len++) {
		seen[len] = __hsiphash_aligned(buf, len, &key);
		for (i = 0; i < len; i++)
			KUNIT_EXPECT_NE_MSG(test, seen[len], seen[i],
					    "len=%zu collides with len=%zu",
					    len, i);
	}
}

static void hsiphash_aligned_every_byte_matters(struct kunit *test)
{
	u64 rng = 7;
	hsiphash_key_t key = rand_key(&rng);
	u8 *buf = alloc_buf(test, 48);
	size_t len, i;

	for (len = 1; len <= 48; len++) {
		u32 base;

		fill_rand(&rng, buf, len);
		base = __hsiphash_aligned(buf, len, &key);
		for (i = 0; i < len; i++) {
			buf[i] ^= 0x01;
			KUNIT_EXPECT_NE_MSG(test, __hsiphash_aligned(buf, len, &key),
					    base, "len=%zu: flip at %zu ignored",
					    len, i);
			buf[i] ^= 0x01;
		}
	}
}

static void hsiphash_aligned_key_matters(struct kunit *test)
{
	static const size_t lens[] = { 0, 1, 5, 8, 13, 16, 33 };
	u64 rng = 8;
	u8 *buf = alloc_buf(test, 40);
	size_t i, bit;

	fill_rand(&rng, buf, 40);
	for (i = 0; i < ARRAY_SIZE(lens); i++) {
		hsiphash_key_t key = rand_key(&rng);
		u32 base = __hsiphash_aligned(buf, lens[i], &key);

		for (bit = 0; bit < 2 * BITS_PER_LONG; bit++) {
			hsiphash_key_t k2 = key;

			k2.key[bit / BITS_PER_LONG] ^= 1UL << (bit % BITS_PER_LONG);
			KUNIT_EXPECT_NE_MSG(test, __hsiphash_aligned(buf, lens[i], &k2),
					    base, "len=%zu: key bit %zu ignored",
					    lens[i], bit);
		}
	}
}

static void hsiphash_aligned_matches_unaligned(struct kunit *test)
{
	u64 rng = 9;
	hsiphash_key_t key = rand_key(&rng);
	u8 *buf = alloc_buf(test, 128 + 8);
	size_t len;

	fill_rand(&rng, buf, 128 + 8);
	for (len = 0; len <= 128; len++)
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(buf, len, &key),
				    __hsiphash_unaligned(buf, len, &key),
				    "len=%zu", len);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(hsiphash_aligned_empty),
	KUNIT_CASE(hsiphash_aligned_tail_only),
	KUNIT_CASE(hsiphash_aligned_block_boundaries),
	KUNIT_CASE(hsiphash_aligned_sweep_small_lengths),
	KUNIT_CASE(hsiphash_aligned_large_lengths),
	KUNIT_CASE(hsiphash_aligned_ignores_bytes_past_end),
	KUNIT_CASE(hsiphash_aligned_length_is_encoded),
	KUNIT_CASE(hsiphash_aligned_every_byte_matters),
	KUNIT_CASE(hsiphash_aligned_key_matters),
	KUNIT_CASE(hsiphash_aligned_matches_unaligned),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

